{
  "name": "5levels-website",
  "version": "1.0.0",
  "description": "Bilingual 5-level educational explanations",
  "private": true,
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview",
    "add-topic": "node scripts/add-topic.js"
  },
  "dependencies": {
    "react": "^18.2.0",
    "react-dom": "^18.2.0",
    "react-router-dom": "^6.21.0"
  },
  "devDependencies": {
    "@vitejs/plugin-react": "^4.2.1",
    "vite": "^5.0.11"
  }
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  build: {
    outDir: 'dist',
    assetsDir: 'assets',
  },
  server: {
    port: 3000,
    host: true,
  },
});

:root {
  /* Typography */
  --font-serif: 'Copernicus', Georgia, 'Times New Roman', serif;
  --font-sans: 'Hanken Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  /* Colors - Base */
  --color-background: #F9F9F9;
  --color-text: #111111;
  --color-text-muted: #666666;
  --color-white: #FFFFFF;
  --color-border: #E0E0E0;

  /* Colors - Levels */
  --color-level-1: #E3B341;
  --color-level-2: #E07A3F;
  --color-level-3: #C06C84;
  --color-level-4: #4C78A8;
  --color-level-5: #2A8F87;

  /* Layout */
  --container-max-width: 800px;
  --border-radius: 24px;
  --border-radius-sm: 12px;
  --border-radius-pill: 999px;

  /* Spacing */
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.08);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;
}

@import './variables.css';

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  background-color: var(--color-background);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
}

/* Typography Scale */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 400;
  line-height: 1.2;
  margin-bottom: 0.5em;
}

h1 {
  font-size: clamp(2rem, 5vw, 3rem);
}

h2 {
  font-size: clamp(1.5rem, 4vw, 2.25rem);
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.75rem);
}

h4 {
  font-size: clamp(1.1rem, 2.5vw, 1.5rem);
}

p {
  margin-bottom: 1em;
}

a {
  color: var(--color-text);
  text-decoration: none;
  transition: opacity var(--transition-fast);
}

a:hover {
  opacity: 0.7;
}

/* Utility Classes */
.container {
  max-width: var(--container-max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.text-muted {
  color: var(--color-text-muted);
}

.text-center {
  text-align: center;
}

/* Level Color Classes */
.level-1 { color: var(--color-level-1); }
.level-2 { color: var(--color-level-2); }
.level-3 { color: var(--color-level-3); }
.level-4 { color: var(--color-level-4); }
.level-5 { color: var(--color-level-5); }

.bg-level-1 { background-color: var(--color-level-1); }
.bg-level-2 { background-color: var(--color-level-2); }
.bg-level-3 { background-color: var(--color-level-3); }
.bg-level-4 { background-color: var(--color-level-4); }
.bg-level-5 { background-color: var(--color-level-5); }

import React from 'react';
import './LanguageToggle.css';

export default function LanguageToggle({ currentLang, onToggle }) {
  return (
    <div className="language-toggle">
      <button
        className={`lang-btn ${currentLang === 'en' ? 'active' : ''}`}
        onClick={() => onToggle('en')}
        aria-label="Switch to English"
      >
        EN
      </button>
      <button
        className={`lang-btn ${currentLang === 'ja' ? 'active' : ''}`}
        onClick={() => onToggle('ja')}
        aria-label="日本語に切り替え"
      >
        日
      </button>
    </div>
  );
}

.language-toggle {
  position: fixed;
  top: var(--spacing-md);
  right: var(--spacing-md);
  display: flex;
  gap: 0;
  background: var(--color-white);
  border-radius: var(--border-radius-pill);
  padding: 4px;
  box-shadow: var(--shadow-md);
  z-index: 100;
}

.lang-btn {
  padding: 0.5rem 1.25rem;
  border: none;
  background: transparent;
  border-radius: var(--border-radius-pill);
  font-family: var(--font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--color-text-muted);
  cursor: pointer;
  transition: all var(--transition-fast);
  min-width: 50px;
}

.lang-btn:hover {
  color: var(--color-text);
}

.lang-btn.active {
  background: var(--color-text);
  color: var(--color-white);
}

@media (max-width: 768px) {
  .language-toggle {
    top: var(--spacing-sm);
    right: var(--spacing-sm);
  }

  .lang-btn {
    padding: 0.4rem 1rem;
    font-size: 0.85rem;
    min-width: 45px;
  }
}

import React from 'react';
import { Link } from 'react-router-dom';
import './Header.css';

export default function Header({ lang }) {
  const text = {
    en: {
      title: '5Levels',
      subtitle: 'Complex concepts explained simply',
      archive: 'Archive',
    },
    ja: {
      title: '5Levels',
      subtitle: '複雑な概念をシンプルに説明',
      archive: 'アーカイブ',
    },
  };

  return (
    <header className="site-header">
      <div className="container">
        <div className="header-content">
          <Link to="/" className="header-brand">
            <h1 className="header-title">{text[lang].title}</h1>
            <p className="header-subtitle text-muted">{text[lang].subtitle}</p>
          </Link>
          <nav className="header-nav">
            <Link to="/" className="nav-link">
              {text[lang].archive}
            </Link>
          </nav>
        </div>
      </div>
    </header>
  );
}

.site-header {
  padding: var(--spacing-xl) 0 var(--spacing-lg);
  background: var(--color-background);
}

.header-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-md);
}

.header-brand {
  text-decoration: none;
}

.header-title {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 5vw, 3rem);
  margin-bottom: 0.25rem;
  color: var(--color-text);
}

.header-subtitle {
  font-size: clamp(0.9rem, 2vw, 1.1rem);
  font-weight: 400;
}

.header-nav {
  display: flex;
  gap: var(--spacing-md);
}

.nav-link {
  font-weight: 500;
  padding: 0.5rem 1rem;
  border-radius: var(--border-radius-sm);
  transition: background var(--transition-fast);
}

.nav-link:hover {
  background: rgba(0, 0, 0, 0.03);
  opacity: 1;
}

@media (max-width: 768px) {
  .site-header {
    padding: var(--spacing-lg) 0 var(--spacing-md);
  }

  .header-content {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-sm);
  }
}

import React from 'react';
import { Link } from 'react-router-dom';
import './TopicCard.css';

export default function TopicCard({ topic, lang }) {
  const colors = topic.colors || {
    level1: '#E3B341',
    level2: '#E07A3F',
    level3: '#C06C84',
    level4: '#4C78A8',
    level5: '#2A8F87',
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return lang === 'en'
      ? date.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
      : date.toLocaleDateString('ja-JP', { year: 'numeric', month: 'long', day: 'numeric' });
  };

  return (
    <Link to={`/topic/${topic.id}`} className="topic-card">
      <div className="card-content">
        <h3 className="card-title">{topic.keyword[lang]}</h3>
        <p className="card-date text-muted">{formatDate(topic.created)}</p>
        <div className="level-dots">
          {[1, 2, 3, 4, 5].map((level) => (
            <div
              key={level}
              className="level-dot"
              style={{ backgroundColor: colors[`level${level}`] }}
              aria-label={`Level ${level}`}
            />
          ))}
        </div>
      </div>
    </Link>
  );
}

.topic-card {
  display: block;
  background: var(--color-white);
  border-radius: var(--border-radius);
  padding: var(--spacing-lg);
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  text-decoration: none;
  color: var(--color-text);
}

.topic-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  opacity: 1;
}

.card-content {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.card-title {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  margin: 0;
}

.card-date {
  font-size: 0.9rem;
}

.level-dots {
  display: flex;
  gap: 0.5rem;
  margin-top: var(--spacing-xs);
}

.level-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  transition: transform var(--transition-fast);
}

.topic-card:hover .level-dot {
  transform: scale(1.1);
}

@media (max-width: 768px) {
  .topic-card {
    padding: var(--spacing-md);
  }
}

import React from 'react';
import './LevelSection.css';

export default function LevelSection({ level, data, color }) {
  return (
    <section className="level-section">
      <div className="level-header">
        <div className="level-indicator" style={{ backgroundColor: color }}>
          <span className="level-number">{level.level}</span>
        </div>
        <h2 className="level-title">{level.title}</h2>
      </div>
      <div className="level-content">
        {level.content.split('\n\n').map((paragraph, idx) => (
          <p key={idx}>{paragraph}</p>
        ))}
      </div>
    </section>
  );
}

.level-section {
  background: var(--color-white);
  border-radius: var(--border-radius);
  padding: var(--spacing-xl);
  box-shadow: var(--shadow-sm);
  margin-bottom: var(--spacing-lg);
}

.level-header {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  margin-bottom: var(--spacing-lg);
}

.level-indicator {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.level-number {
  font-family: var(--font-sans);
  font-weight: 700;
  font-size: 1.5rem;
  color: var(--color-white);
}

.level-title {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  margin: 0;
}

.level-content {
  font-size: clamp(1rem, 2vw, 1.1rem);
  line-height: 1.8;
}

.level-content p {
  margin-bottom: 1.25em;
}

.level-content p:last-child {
  margin-bottom: 0;
}

@media (max-width: 768px) {
  .level-section {
    padding: var(--spacing-lg);
  }

  .level-indicator {
    width: 40px;
    height: 40px;
  }

  .level-number {
    font-size: 1.25rem;
  }
}

import React, { useState, useEffect } from 'react';
import TopicCard from '../components/TopicCard';
import './Archive.css';

export default function Archive({ lang }) {
  const [topics, setTopics] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Load topics from data directory
    fetch('/data/topics-index.json')
      .then((res) => res.json())
      .then((data) => {
        setTopics(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error('Failed to load topics:', err);
        setLoading(false);
      });
  }, []);

  const text = {
    en: {
      title: 'Archive',
      subtitle: 'Explore topics explained in 5 levels',
      search: 'Search topics...',
      noResults: 'No topics found',
      loading: 'Loading topics...',
    },
    ja: {
      title: 'アーカイブ',
      subtitle: '5つのレベルで説明されたトピックを探索',
      search: 'トピックを検索...',
      noResults: 'トピックが見つかりません',
      loading: 'トピックを読み込み中...',
    },
  };

  const filteredTopics = topics.filter((topic) =>
    topic.keyword[lang].toLowerCase().includes(searchQuery.toLowerCase())
  );

  if (loading) {
    return (
      <div className="archive-page">
        <div className="container">
          <p className="text-center text-muted">{text[lang].loading}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="archive-page">
      <div className="container">
        <div className="archive-header">
          <h2 className="archive-title">{text[lang].title}</h2>
          <p className="archive-subtitle text-muted">{text[lang].subtitle}</p>
        </div>

        <div className="search-bar">
          <input
            type="text"
            placeholder={text[lang].search}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="search-input"
          />
        </div>

        {filteredTopics.length === 0 ? (
          <p className="text-center text-muted">{text[lang].noResults}</p>
        ) : (
          <div className="topics-grid">
            {filteredTopics.map((topic) => (
              <TopicCard key={topic.id} topic={topic} lang={lang} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

.archive-page {
  padding: var(--spacing-xl) 0 var(--spacing-2xl);
  min-height: 60vh;
}

.archive-header {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.archive-title {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 5vw, 3rem);
  margin-bottom: var(--spacing-sm);
}

.archive-subtitle {
  font-size: clamp(1rem, 2vw, 1.2rem);
}

.search-bar {
  margin-bottom: var(--spacing-xl);
}

.search-input {
  width: 100%;
  padding: var(--spacing-md);
  border: 2px solid var(--color-border);
  border-radius: var(--border-radius-sm);
  font-family: var(--font-sans);
  font-size: 1rem;
  background: var(--color-white);
  transition: border-color var(--transition-fast);
}

.search-input:focus {
  outline: none;
  border-color: var(--color-text);
}

.topics-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: var(--spacing-lg);
}

@media (max-width: 768px) {
  .archive-page {
    padding: var(--spacing-lg) 0 var(--spacing-xl);
  }

  .topics-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }
}

import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import LevelSection from '../components/LevelSection';
import './TopicDetail.css';

export default function TopicDetail({ lang }) {
  const { id } = useParams();
  const [topic, setTopic] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`/data/topics/${id}.json`)
      .then((res) => res.json())
      .then((data) => {
        setTopic(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error('Failed to load topic:', err);
        setLoading(false);
      });
  }, [id]);

  const text = {
    en: {
      back: '← Back to Archive',
      sources: 'Sources',
      loading: 'Loading...',
      notFound: 'Topic not found',
    },
    ja: {
      back: '← アーカイブに戻る',
      sources: '出典',
      loading: '読み込み中...',
      notFound: 'トピックが見つかりません',
    },
  };

  if (loading) {
    return (
      <div className="topic-detail">
        <div className="container">
          <p className="text-center text-muted">{text[lang].loading}</p>
        </div>
      </div>
    );
  }

  if (!topic) {
    return (
      <div className="topic-detail">
        <div className="container">
          <p className="text-center text-muted">{text[lang].notFound}</p>
          <div className="text-center" style={{ marginTop: 'var(--spacing-lg)' }}>
            <Link to="/" className="back-link">
              {text[lang].back}
            </Link>
          </div>
        </div>
      </div>
    );
  }

  const colors = topic.colors || {
    level1: '#E3B341',
    level2: '#E07A3F',
    level3: '#C06C84',
    level4: '#4C78A8',
    level5: '#2A8F87',
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    return lang === 'en'
      ? date.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
      : date.toLocaleDateString('ja-JP', { year: 'numeric', month: 'long', day: 'numeric' });
  };

  return (
    <div className="topic-detail">
      <div className="container">
        <Link to="/" className="back-link">
          {text[lang].back}
        </Link>

        <div className="topic-header">
          <h1 className="topic-title">{topic.keyword[lang]}</h1>
          <p className="topic-date text-muted">{formatDate(topic.created)}</p>
        </div>

        <div className="levels-container">
          {topic.levels[lang].map((level) => (
            <LevelSection
              key={level.level}
              level={level}
              color={colors[`level${level.level}`]}
            />
          ))}
        </div>

        {topic.sources && topic.sources.length > 0 && (
          <div className="sources-section">
            <h3 className="sources-title">{text[lang].sources}</h3>
            <ul className="sources-list">
              {topic.sources.map((source, idx) => (
                <li key={idx} className="source-item">
                  <a
                    href={source.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="source-link"
                  >
                    {source.title}
                  </a>
                  <span className="source-lang text-muted">({source.language})</span>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </div>
  );
}

.topic-detail {
  padding: var(--spacing-xl) 0 var(--spacing-2xl);
  min-height: 70vh;
}

.back-link {
  display: inline-block;
  margin-bottom: var(--spacing-lg);
  font-weight: 500;
  color: var(--color-text-muted);
  transition: color var(--transition-fast);
}

.back-link:hover {
  color: var(--color-text);
  opacity: 1;
}

.topic-header {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.topic-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 4rem);
  margin-bottom: var(--spacing-sm);
}

.topic-date {
  font-size: 1rem;
}

.levels-container {
  margin-bottom: var(--spacing-2xl);
}

.sources-section {
  background: var(--color-white);
  border-radius: var(--border-radius);
  padding: var(--spacing-xl);
  box-shadow: var(--shadow-sm);
}

.sources-title {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  margin-bottom: var(--spacing-md);
}

.sources-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.source-item {
  display: flex;
  gap: var(--spacing-xs);
  align-items: baseline;
}

.source-link {
  color: var(--color-text);
  text-decoration: underline;
  text-decoration-color: var(--color-border);
  transition: text-decoration-color var(--transition-fast);
}

.source-link:hover {
  text-decoration-color: var(--color-text);
  opacity: 1;
}

.source-lang {
  font-size: 0.9rem;
  white-space: nowrap;
}

@media (max-width: 768px) {
  .topic-detail {
    padding: var(--spacing-lg) 0 var(--spacing-xl);
  }

  .topic-header {
    margin-bottom: var(--spacing-xl);
  }

  .sources-section {
    padding: var(--spacing-lg);
